Process_Node* process_create_cfg( Process_Cfg* const cfg )
{
    Process_Node *process = process_create( cfg->name );
    
    if( process )
    {
        process->id              = cfg->own_id       ; 
        process->is_blocked_by   = cfg->blocked_by   ; 
        process->is_suspended_by = cfg->suspended_by ; 

        process->start           = cfg->start        ;
        process->exec            = cfg->exec         ;
        process->stop            = cfg->stop         ;

        process->timeout         = cfg->timeout/10   ;

        process->no_timeout      = !cfg->timeout     ;
    }

    return process ; 
}

